// ─────────────────────────────────────────────────────────────────────────
//  01 · bounded LRU cache★★☆
//  concepts: LinkedHashMap access order · removeEldestEntry
// ─────────────────────────────────────────────────────────────────────────

import static bootcamp.Check.*;

import java.util.*;

class Exercise {

    /** A size-bounded map that evicts the least recently used entry. */
    static <K, V> Map<K, V> lruCache(int maxEntries) {
        if (maxEntries < 1) throw new IllegalArgumentException("maxEntries must be >= 1");
        return new LinkedHashMap<>(16, 0.75f, true) {
            @Override
            protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
                return size() > maxEntries;
            }
        };
    }

    // ─── tests ───────────────────────────────────────────────────────────
    public static void main(String[] args) {
        test("a read refreshes an entry", () -> {
            Map<String, Integer> c = lruCache(2);
            c.put("a", 1);
            c.put("b", 2);
            c.get("a");
            c.put("c", 3);
            eq(new ArrayList<>(c.keySet()), List.of("a", "c"));
        });
        test("never more than the limit", () -> {
            Map<Integer, Integer> c = lruCache(100);
            for (int i = 0; i < 10_000; i++) c.put(i, i);
            eq(c.size(), 100);
            ok(c.containsKey(9_999) && !c.containsKey(0), "keeps the newest entries");
        });
        test("containsKey does not count as a use", () -> {
            Map<String, Integer> c = lruCache(2);
            c.put("a", 1);
            c.put("b", 2);
            c.containsKey("a");
            c.put("c", 3);
            ok(!c.containsKey("a"), "a should have been evicted");
        });
        test("a limit of one keeps the latest entry (boundary)", () -> {
            Map<String, Integer> c = lruCache(1);
            c.put("a", 1);
            c.put("b", 2);
            eq(c, Map.of("b", 2));
        });
        test("a limit below one is rejected", () -> raises(IllegalArgumentException.class, () -> lruCache(0)));
        System.exit(report());
    }
    // ─── end tests ───────────────────────────────────────────────────────
}

drills.explanation:
Use the three-argument constructor with `accessOrder = true` and override `removeEldestEntry`:

```java
if (maxEntries < 1) throw new IllegalArgumentException("maxEntries must be >= 1");
return new LinkedHashMap<>(16, 0.75f, true) {
    @Override protected boolean removeEldestEntry(Map.Entry<K, V> eldest) {
        return size() > maxEntries;
    }
};
```

The map calls `removeEldestEntry` after each insertion; returning true evicts the head of the list, which in access order is the least recently used entry. With `accessOrder = false` (the default) you would get FIFO eviction, which fails the "get refreshes" test.
